@Test
public void testSplit() {
    assertEquals(Arrays.asList(new String[0]), sqlScriptParser.split(null));
    assertEquals(Arrays.asList(new String[0]), sqlScriptParser.split(""));
    assertEquals(Arrays.asList(new String[0]), sqlScriptParser.split(" "));
    assertEquals(Arrays.asList("SELECT 1", "SELECT 2"), sqlScriptParser.split("SELECT 1;SELECT 2"));
    assertEquals(Collections.singletonList("SELECT '1;2'"), sqlScriptParser.split("SELECT '1;2'"));
    assertEquals(Collections.singletonList("SELECT \"1;2\""), sqlScriptParser.split("SELECT \"1;2\""));
    assertEquals(Collections.singletonList("SELECT -- 1;2"), sqlScriptParser.split("SELECT -- 1;2"));
    assertEquals(Collections.singletonList("SELECT /*1;2*/"), sqlScriptParser.split("SELECT /*1;2*/"));
    assertEquals(Arrays.asList("SELECT /1", "2"), sqlScriptParser.split("SELECT /1;2"));
    assertEquals(Arrays.asList("SELECT /1", "2"), sqlScriptParser.split("SELECT /1;;;;2"));
    assertEquals(Collections.singletonList("SELECT /1"), sqlScriptParser.split("SELECT /1;\n  \n"));
    assertEquals(Collections.singletonList("SELECT \"hello\\\"world\" FROM dual"), sqlScriptParser.split("SELECT \"hello\\\"world\" FROM dual"));
    assertEquals(Collections.singletonList("CREATE TABLE test1 (col1 STRING) TBLPROPERTIES (\"prop1\" = \"my\\\"value\")"), sqlScriptParser.split("CREATE TABLE test1 (col1 STRING) TBLPROPERTIES (\"prop1\" = \"my\\\"value\");"));
    assertEquals(Collections.singletonList("CREATE TABLE test1 (col1 STRING) TBLPROPERTIES ('prop1' = 'my\\\"value')"), sqlScriptParser.split("CREATE TABLE test1 (col1 STRING) TBLPROPERTIES ('prop1' = 'my\\\"value');"));
    assertEquals(Collections.singletonList("SELECT \"test\\\";SELECT 1"), sqlScriptParser.split("SELECT \"test\\\";SELECT 1"));
    assertEquals(Collections.singletonList("SELECT 'test\\';SELECT 1"), sqlScriptParser.split("SELECT 'test\\';SELECT 1"));
    assertEquals(Arrays.asList("create table pdi13654 (col1 string) TBLPROPERTIES (\"quoteChar\"=\"\\\"\", \"escapeChar\"=\"\\\\\")", "SELECT 1"), sqlScriptParser.split("create table pdi13654 (col1 string) TBLPROPERTIES (\"quoteChar\"=\"\\\"\", \"escapeChar\"=\"\\\\\");SELECT 1"));
    assertEquals(Collections.singletonList("SELECT 1 from test where t='\\'||t=a"), oracleSqlScriptParser.split("SELECT 1 from test where t='\\'||t=a;"));
}

@Test
public void testRemoveComments() {
    assertEquals(null, sqlScriptParser.removeComments(null));
    assertEquals("", sqlScriptParser.removeComments(""));
    assertEquals("SELECT col1 FROM test", sqlScriptParser.removeComments("SELECT col1 FROM test"));
    assertEquals("SELECT col1 FROM test ", sqlScriptParser.removeComments("SELECT col1 FROM test --end comment"));
    assertEquals("SELECT \n col1, col2\n FROM \n test", sqlScriptParser.removeComments("SELECT \n col1, col2\n FROM \n test"));
    assertEquals("SELECT \n \"col1\", col2\n FROM \n test", sqlScriptParser.removeComments("SELECT \n \"col1\", col2\n FROM --test\n test"));
    assertEquals("SELECT  col1 FROM  account", sqlScriptParser.removeComments("SELECT /* \"my_column'\" */ col1 FROM /* 'my_table' */ account"));
    assertEquals("SELECT '/' as col1, '*/*' as regex ", sqlScriptParser.removeComments("SELECT '/' as col1, '*/*' as regex "));
    assertEquals("SELECT INSTR('/loader/*/*.txt', '/') - INSTR('/loader/*/*.txt', '/') ", sqlScriptParser.removeComments("SELECT INSTR('/loader/*/*.txt', '/') - INSTR('/loader/*/*.txt', '/') "));
    assertEquals("SELECT  col1, col2, col3 FROM account WHERE name = 'Apache Hop'", sqlScriptParser.removeComments("SELECT /* my data*/ col1, col2, col3 FROM account WHERE name = 'Apache Hop'"));
    assertEquals("SELECT /*+ ORACLE hint*/ col1, col2, col3 FROM account WHERE name = 'Apache Hop'", sqlScriptParser.removeComments("SELECT /*+ ORACLE hint*/ col1, col2, col3 FROM account WHERE name = 'Apache Hop'"));
    assertEquals("SELECT \n/*+ ORACLE hint*/ col1, col2, col3 FROM account WHERE name = 'Apache Hop'", sqlScriptParser.removeComments("SELECT \n/*+ ORACLE hint*/ col1, col2, col3 FROM account WHERE name = 'Apache Hop'"));
    assertEquals("SELECT \n/*+ ORACLE hint*/\n col1, col2, col3 FROM account WHERE name = 'Apache Hop'", sqlScriptParser.removeComments("SELECT \n/*+ ORACLE hint*/\n col1, col2, col3 FROM account WHERE name = 'Apache Hop'"));
    assertEquals("SELECT \"hello\\\"world\" FROM dual", sqlScriptParser.removeComments("SELECT \"hello\\\"world\" FROM dual"));
    assertEquals("CREATE TABLE test1 (col1 STRING) TBLPROPERTIES (\"prop1\" = \"my\\\"value\")", sqlScriptParser.removeComments("CREATE TABLE test1 (col1 STRING) TBLPROPERTIES (\"prop1\" = \"my\\\"value\")"));
    assertEquals("CREATE TABLE test1 (col1 STRING) TBLPROPERTIES ('prop1' = 'my\\\"value')", sqlScriptParser.removeComments("CREATE TABLE test1 (col1 STRING) TBLPROPERTIES ('prop1' = 'my\\\"value')"));
    assertEquals("SELECT 1 from test where t='\\'||t=a", oracleSqlScriptParser.removeComments("SELECT 1 from test where t='\\'/* comment */||t=a"));
}

@Test
public void testClass() throws IOException, HopFileException {
    final String dbName = "dbName";
    final String sql = "sql query";
    DbCacheEntry entry = new DbCacheEntry(dbName, sql);
    assertTrue(entry.sameDB("dbName"));
    assertFalse(entry.sameDB("otherDb"));
    assertEquals(dbName.toLowerCase().hashCode() ^ sql.toLowerCase().hashCode(), entry.hashCode());
    DbCacheEntry otherEntry = new DbCacheEntry();
    assertFalse(otherEntry.sameDB("otherDb"));
    assertEquals(0, otherEntry.hashCode());
    assertNotEquals(entry, otherEntry);
    assertNotEquals(entry, new Object());
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    DataOutputStream dos = new DataOutputStream(baos);
    dos.writeUTF(dbName);
    dos.writeUTF(sql);
    byte[] bytes = baos.toByteArray();
    InputStream is = new ByteArrayInputStream(bytes);
    DataInputStream dis = new DataInputStream(is);
    DbCacheEntry disEntry = new DbCacheEntry(dis);
    assertEquals(disEntry, entry);
    try {
        new DbCacheEntry(dis);
        fail("Should throw HopEofException on EOFException");
    } catch (HopEofException keofe) {
        // Ignore
    }
    baos.reset();
    assertTrue(disEntry.write(dos));
    assertArrayEquals(bytes, baos.toByteArray());
}

/**
 * Test password encryption.
 *
 * @throws HopValueException
 */
@Test
public void testEncryptPassword() {
    String encryption;
    encryption = Encr.encryptPassword(null);
    assertEquals("", encryption);
    encryption = Encr.encryptPassword("");
    assertEquals("", encryption);
    encryption = Encr.encryptPassword("     ");
    assertEquals("2be98afc86aa7f2e4cb79ce309ed2ef9a", encryption);
    encryption = Encr.encryptPassword("Test of different encryptions!!@#$%");
    assertEquals("54657374206f6620646966666572656e742067d0fbddb11ad39b8ba50aef31fed1eb9f", encryption);
    encryption = Encr.encryptPassword("  Spaces left");
    assertEquals("2be98afe84af48285a81cbd30d297a9ce", encryption);
    encryption = Encr.encryptPassword("Spaces right");
    assertEquals("2be98afc839d79387ae0aee62d795a7ce", encryption);
    encryption = Encr.encryptPassword("     Spaces  ");
    assertEquals("2be98afe84a87d2c49809af73db81ef9a", encryption);
    encryption = Encr.encryptPassword("1234567890");
    assertEquals("2be98afc86aa7c3d6f84dfb2689caf68a", encryption);
}

/**
