    assertEquals("", decryption);
    encryption = encoder.encode("String");
    decryption = encoder.decode(encryption);
    assertEquals("String", decryption);
    encryption = encoder.encode(" ${VAR} String", false);
    decryption = encoder.decode(encryption);
    assertEquals(" ${VAR} String", decryption);
    encryption = encoder.encode(" %%VAR%% String", false);
    decryption = encoder.decode(encryption);
    assertEquals(" %%VAR%% String", decryption);
    encryption = encoder.encode(" %% VAR String", false);
    decryption = encoder.decode(encryption);
    assertEquals(" %% VAR String", decryption);
