@Test
public void testNeedRealClone() {
    RowMeta newRowMeta = new RowMeta();
    newRowMeta.addValueMeta(string);
    newRowMeta.addValueMeta(integer);
    newRowMeta.addValueMeta(date);
    newRowMeta.addValueMeta(charly);
    newRowMeta.addValueMeta(dup);
    newRowMeta.addValueMeta(bin);
    List<Integer> list = newRowMeta.getOrCreateValuesThatNeedRealClone(newRowMeta.valueMetaList);
    // Should be charly, dup and bin
    assertEquals(3, list.size());
    // charly
    assertTrue(list.contains(3));
    // dup
    assertTrue(list.contains(4));
    // bin
    assertTrue(list.contains(5));
    // should have nulled the newRowMeta.needRealClone
    newRowMeta.addValueMeta(charly);
    // null because of the new add
    assertNull(newRowMeta.needRealClone);
    list = newRowMeta.getOrCreateValuesThatNeedRealClone(newRowMeta.valueMetaList);
    assertNotNull(newRowMeta.needRealClone);
    // Should still be charly, dup, bin, charly_1
    assertEquals(4, list.size());
    // add new binary, should null out needRealClone again
    newRowMeta.addValueMeta(bin);
    // null because of the new add
    assertNull(newRowMeta.needRealClone);
    list = newRowMeta.getOrCreateValuesThatNeedRealClone(newRowMeta.valueMetaList);
    assertNotNull(newRowMeta.needRealClone);
    // Should be charly, dup and bin, charly_1, bin_1
    assertEquals(5, list.size());
    // add new string, should null out needRealClone again
    newRowMeta.addValueMeta(string);
    // null because of the new add
    assertNull(newRowMeta.needRealClone);
    list = newRowMeta.getOrCreateValuesThatNeedRealClone(newRowMeta.valueMetaList);
    assertNotNull(newRowMeta.needRealClone);
    assertEquals(5, // Should still only be charly, dup and bin, charly_1, bin_1 - adding a string
    list.size());
    // doesn't change of result
}

