@Test
public void testStoreLoadMetaInJson() throws Exception {
    Schema schema = new Schema.Parser().parse(SCHEMA_JSON);
    ValueMetaAvroRecord valueMeta = new ValueMetaAvroRecord("test", schema);
    JSONObject jValue = new JSONObject();
    valueMeta.storeMetaInJson(jValue);
    ObjectMapper mapper = new ObjectMapper();
    JsonNode valueNode = mapper.readTree(jValue.toJSONString());
    JsonNode expectJsonNode = mapper.readTree("{\"schema\":{\"name\":\"all_values\",\"namespace\":\"hop.apache.org\",\"doc\":" + "\"No documentation URL for now\",\"type\":\"record\",\"fields\":[{\"name\":\"id\",\"type\":" + "[\"long\",\"null\"]},{\"name\":\"sysdate\",\"type\":[\"string\",\"null\"]}," + "{\"name\":\"num\",\"type\":[\"double\",\"null\"]},{\"name\":\"int\",\"type\":" + "[\"long\",\"null\"]},{\"name\":\"str\",\"type\":[\"string\",\"null\"]}," + "{\"name\":\"uuid\",\"type\":[\"string\",\"null\"]}]},\"precision\":-1,\"name\":" + "\"test\",\"length\":-1,\"conversionMask\":null,\"type\":20}");
    assertEquals(valueNode, expectJsonNode);
    // Read it back...
    //
    JSONObject jLoaded = (JSONObject) new JSONParser().parse(valueNode.toString());
    ValueMetaAvroRecord loaded = (ValueMetaAvroRecord) ValueMetaFactory.loadValueMetaFromJson(jLoaded);
    assertEquals(valueMeta.getName(), loaded.getName());
    assertEquals(valueMeta.getSchema().toString(true), loaded.getSchema().toString(true));
}

