@Test
public void testMultithreadHammeringOfListener() throws Exception {
    CountDownLatch latch = new CountDownLatch(3);
    AbstractMetaListenerThread th1 = // do 1M random add/delete/fire
    new AbstractMetaListenerThread(meta, 1000000, latch, 50);
    AbstractMetaListenerThread th2 = // do 1M random add/delete/fire
    new AbstractMetaListenerThread(meta, 1000000, latch, 50);
    AbstractMetaListenerThread th3 = // do 1M random add/delete/fire
    new AbstractMetaListenerThread(meta, 1000000, latch, 50);
    Thread t1 = new Thread(th1);
    Thread t2 = new Thread(th2);
    Thread t3 = new Thread(th3);
    try {
        t1.start();
        t2.start();
        t3.start();
        // Will hang out waiting for each thread to complete...
        latch.await();
    } catch (InterruptedException badTest) {
        throw badTest;
    }
    assertEquals("No exceptions encountered", th1.message);
    assertEquals("No exceptions encountered", th2.message);
    assertEquals("No exceptions encountered", th3.message);
}

