@Test
void testAdd() {
    // Test Hop number types
    assertEquals(Double.valueOf("3.0"), calculate("1", "2", IValueMeta.TYPE_NUMBER, CalculationType.ADD));
    assertEquals(Double.valueOf("0.0"), calculate("2", "-2", IValueMeta.TYPE_NUMBER, CalculationType.ADD));
    assertEquals(Double.valueOf("30.0"), calculate("10", "20", IValueMeta.TYPE_NUMBER, CalculationType.ADD));
    assertEquals(Double.valueOf("-50.0"), calculate("-100", "50", IValueMeta.TYPE_NUMBER, CalculationType.ADD));
    // Test Hop Integer (Java Long) types
    assertEquals(Long.valueOf("3"), calculate("1", "2", IValueMeta.TYPE_INTEGER, CalculationType.ADD));
    assertEquals(Long.valueOf("0"), calculate("2", "-2", IValueMeta.TYPE_INTEGER, CalculationType.ADD));
    assertEquals(Long.valueOf("30"), calculate("10", "20", IValueMeta.TYPE_INTEGER, CalculationType.ADD));
    assertEquals(Long.valueOf("-50"), calculate("-100", "50", IValueMeta.TYPE_INTEGER, CalculationType.ADD));
    // Test Hop big Number types
    assertEquals(0, new BigDecimal("2.0").compareTo((BigDecimal) calculate("1", "1", IValueMeta.TYPE_BIGNUMBER, CalculationType.ADD)));
    assertEquals(0, new BigDecimal("0.0").compareTo((BigDecimal) calculate("2", "-2", IValueMeta.TYPE_BIGNUMBER, CalculationType.ADD)));
    assertEquals(0, new BigDecimal("30.0").compareTo((BigDecimal) calculate("10", "20", IValueMeta.TYPE_BIGNUMBER, CalculationType.ADD)));
    assertEquals(0, new BigDecimal("-50.0").compareTo((BigDecimal) calculate("-100", "50", IValueMeta.TYPE_BIGNUMBER, CalculationType.ADD)));
}

