    assertEquals(Double.valueOf("1.0"), calculate("1", IValueMeta.TYPE_NUMBER, CalculationType.ROUND_1));
    assertEquals(Double.valueOf("103.0"), calculate("103.01", IValueMeta.TYPE_NUMBER, CalculationType.ROUND_1));
    assertEquals(Double.valueOf("1235.0"), calculate("1234.6", IValueMeta.TYPE_NUMBER, CalculationType.ROUND_1));
    // half
    assertEquals(Double.valueOf("1235.0"), calculate("1234.5", IValueMeta.TYPE_NUMBER, CalculationType.ROUND_1));
    assertEquals(Double.valueOf("1236.0"), calculate("1235.5", IValueMeta.TYPE_NUMBER, CalculationType.ROUND_1));
    assertEquals(Double.valueOf("-1234.0"), calculate("-1234.5", IValueMeta.TYPE_NUMBER, CalculationType.ROUND_1));
    assertEquals(Double.valueOf("-1235.0"), calculate("-1235.5", IValueMeta.TYPE_NUMBER, CalculationType.ROUND_1));
    // Test Hop Integer (Java Long) types
    assertEquals(Long.valueOf("1"), calculate("1", IValueMeta.TYPE_INTEGER, CalculationType.ROUND_1));
    assertEquals(Long.valueOf("2"), calculate("2", IValueMeta.TYPE_INTEGER, CalculationType.ROUND_1));
    assertEquals(Long.valueOf("-103"), calculate("-103", IValueMeta.TYPE_INTEGER, CalculationType.ROUND_1));
    // Test Hop big Number types
    assertEquals(BigDecimal.ONE, calculate("1", IValueMeta.TYPE_BIGNUMBER, CalculationType.ROUND_1));
    assertEquals(BigDecimal.valueOf(Long.parseLong("103")), calculate("103.01", IValueMeta.TYPE_BIGNUMBER, CalculationType.ROUND_1));
    assertEquals(BigDecimal.valueOf(Long.parseLong("1235")), calculate("1234.6", IValueMeta.TYPE_BIGNUMBER, CalculationType.ROUND_1));
    // half
    assertEquals(BigDecimal.valueOf(Long.parseLong("1235")), calculate("1234.5", IValueMeta.TYPE_BIGNUMBER, CalculationType.ROUND_1));
    assertEquals(BigDecimal.valueOf(Long.parseLong("1236")), calculate("1235.5", IValueMeta.TYPE_BIGNUMBER, CalculationType.ROUND_1));
    assertEquals(BigDecimal.valueOf(Long.parseLong("-1234")), calculate("-1234.5", IValueMeta.TYPE_BIGNUMBER, CalculationType.ROUND_1));
    assertEquals(BigDecimal.valueOf(Long.parseLong("-1235")), calculate("-1235.5", IValueMeta.TYPE_BIGNUMBER, CalculationType.ROUND_1));
}

@Test
void testRound2() {
    // Test Hop number types
    assertEquals(Double.valueOf("1.0"), calculate("1", "1", IValueMeta.TYPE_NUMBER, CalculationType.ROUND_2));
    assertEquals(Double.valueOf("2.1"), calculate("2.06", "1", IValueMeta.TYPE_NUMBER, CalculationType.ROUND_2));
    assertEquals(Double.valueOf("103.0"), calculate("103.01", "1", IValueMeta.TYPE_NUMBER, CalculationType.ROUND_2));
    assertEquals(Double.valueOf("12.35"), calculate("12.346", "2", IValueMeta.TYPE_NUMBER, CalculationType.ROUND_2));
    // scale < 0
    assertEquals(Double.valueOf("10.0"), calculate("12.0", "-1", IValueMeta.TYPE_NUMBER, CalculationType.ROUND_2));
    // half
    assertEquals(Double.valueOf("12.35"), calculate("12.345", "2", IValueMeta.TYPE_NUMBER, CalculationType.ROUND_2));
    assertEquals(Double.valueOf("12.36"), calculate("12.355", "2", IValueMeta.TYPE_NUMBER, CalculationType.ROUND_2));
    assertEquals(Double.valueOf("-12.34"), calculate("-12.345", "2", IValueMeta.TYPE_NUMBER, CalculationType.ROUND_2));
    assertEquals(Double.valueOf("-12.35"), calculate("-12.355", "2", IValueMeta.TYPE_NUMBER, CalculationType.ROUND_2));
    // Test Hop Integer (Java Long) types
    assertEquals(Long.valueOf("1"), calculate("1", "1", IValueMeta.TYPE_INTEGER, CalculationType.ROUND_2));
    assertEquals(Long.valueOf("2"), calculate("2", "2", IValueMeta.TYPE_INTEGER, CalculationType.ROUND_2));
    assertEquals(Long.valueOf("103"), calculate("103", "3", IValueMeta.TYPE_INTEGER, CalculationType.ROUND_2));
    assertEquals(Long.valueOf("12"), calculate("12", "4", IValueMeta.TYPE_INTEGER, CalculationType.ROUND_2));
    // scale < 0
    assertEquals(Long.valueOf("100"), calculate("120", "-2", IValueMeta.TYPE_INTEGER, CalculationType.ROUND_2));
    // half
    assertEquals(Long.valueOf("12350"), calculate("12345", "-1", IValueMeta.TYPE_INTEGER, CalculationType.ROUND_2));
    assertEquals(Long.valueOf("12360"), calculate("12355", "-1", IValueMeta.TYPE_INTEGER, CalculationType.ROUND_2));
    assertEquals(Long.valueOf("-12340"), calculate("-12345", "-1", IValueMeta.TYPE_INTEGER, CalculationType.ROUND_2));
    assertEquals(Long.valueOf("-12350"), calculate("-12355", "-1", IValueMeta.TYPE_INTEGER, CalculationType.ROUND_2));
    // Test Hop big Number types
    assertEquals(BigDecimal.valueOf(Double.parseDouble("1.0")), calculate("1", "1", IValueMeta.TYPE_BIGNUMBER, CalculationType.ROUND_2));
    assertEquals(BigDecimal.valueOf(Double.parseDouble("2.1")), calculate("2.06", "1", IValueMeta.TYPE_BIGNUMBER, CalculationType.ROUND_2));
    assertEquals(BigDecimal.valueOf(Double.parseDouble("103.0")), calculate("103.01", "1", IValueMeta.TYPE_BIGNUMBER, CalculationType.ROUND_2));
    assertEquals(BigDecimal.valueOf(Double.parseDouble("12.35")), calculate("12.346", "2", IValueMeta.TYPE_BIGNUMBER, CalculationType.ROUND_2));
    // scale < 0
    assertEquals(BigDecimal.valueOf(Double.parseDouble("10.0")).setScale(-1), calculate("12.0", "-1", IValueMeta.TYPE_BIGNUMBER, CalculationType.ROUND_2));
    // half
    assertEquals(BigDecimal.valueOf(Double.parseDouble("12.35")), calculate("12.345", "2", IValueMeta.TYPE_BIGNUMBER, CalculationType.ROUND_2));
    assertEquals(BigDecimal.valueOf(Double.parseDouble("12.36")), calculate("12.355", "2", IValueMeta.TYPE_BIGNUMBER, CalculationType.ROUND_2));
    assertEquals(BigDecimal.valueOf(Double.parseDouble("-12.34")), calculate("-12.345", "2", IValueMeta.TYPE_BIGNUMBER, CalculationType.ROUND_2));
    assertEquals(BigDecimal.valueOf(Double.parseDouble("-12.35")), calculate("-12.355", "2", IValueMeta.TYPE_BIGNUMBER, CalculationType.ROUND_2));
}

@Test
void testNVL() {
    // Test Hop number types
    assertEquals(Double.valueOf("1.0"), calculate("1", "", IValueMeta.TYPE_NUMBER, CalculationType.NVL));
    assertEquals(Double.valueOf("2.0"), calculate("", "2", IValueMeta.TYPE_NUMBER, CalculationType.NVL));
    assertEquals(Double.valueOf("10.0"), calculate("10", "20", IValueMeta.TYPE_NUMBER, CalculationType.NVL));
    assertNull(calculate("", "", IValueMeta.TYPE_NUMBER, CalculationType.NVL));
    // Test Hop string types
    assertEquals("1", calculate("1", "", IValueMeta.TYPE_STRING, CalculationType.NVL));
    assertEquals("2", calculate("", "2", IValueMeta.TYPE_STRING, CalculationType.NVL));
    assertEquals("10", calculate("10", "20", IValueMeta.TYPE_STRING, CalculationType.NVL));
    assertNull(calculate("", "", IValueMeta.TYPE_STRING, CalculationType.NVL));
    // Test Hop Integer (Java Long) types
    assertEquals(Long.valueOf("1"), calculate("1", "", IValueMeta.TYPE_INTEGER, CalculationType.NVL));
    assertEquals(Long.valueOf("2"), calculate("", "2", IValueMeta.TYPE_INTEGER, CalculationType.NVL));
    assertEquals(Long.valueOf("10"), calculate("10", "20", IValueMeta.TYPE_INTEGER, CalculationType.NVL));
    assertNull(calculate("", "", IValueMeta.TYPE_INTEGER, CalculationType.NVL));
    // Test Hop big Number types
    assertEquals(0, new BigDecimal("1").compareTo((BigDecimal) calculate("1", "", IValueMeta.TYPE_BIGNUMBER, CalculationType.NVL)));
    assertEquals(0, new BigDecimal("2").compareTo((BigDecimal) calculate("", "2", IValueMeta.TYPE_BIGNUMBER, CalculationType.NVL)));
    assertEquals(0, new BigDecimal("10").compareTo((BigDecimal) calculate("10", "20", IValueMeta.TYPE_BIGNUMBER, CalculationType.NVL)));
    assertNull(calculate("", "", IValueMeta.TYPE_BIGNUMBER, CalculationType.NVL));
    // boolean
    assertEquals(true, calculate("true", "", IValueMeta.TYPE_BOOLEAN, CalculationType.NVL));
    assertEquals(false, calculate("", "false", IValueMeta.TYPE_BOOLEAN, CalculationType.NVL));
    assertEquals(false, calculate("false", "true", IValueMeta.TYPE_BOOLEAN, CalculationType.NVL));
    assertNull(calculate("", "", IValueMeta.TYPE_BOOLEAN, CalculationType.NVL));
    // Test Hop date
    SimpleDateFormat simpleDateFormat = new SimpleDateFormat(YYYY_MM_DD);
    try {
        assertEquals(simpleDateFormat.parse("2012-04-11"), calculate("2012-04-11", "", IValueMeta.TYPE_DATE, CalculationType.NVL));
        assertEquals(simpleDateFormat.parse("2012-11-04"), calculate("", "2012-11-04", IValueMeta.TYPE_DATE, CalculationType.NVL));
        assertEquals(simpleDateFormat.parse("1965-07-01"), calculate("1965-07-01", "1967-04-11", IValueMeta.TYPE_DATE, CalculationType.NVL));
        assertNull(calculate("", "", IValueMeta.TYPE_DATE, CalculationType.NVL));
    } catch (ParseException pe) {
        fail(pe.getMessage());
    }
    // binary
    IValueMeta stringValueMeta = new ValueMetaString("string");
    try {
        byte[] data = stringValueMeta.getBinary("101");
        byte[] calculated = (byte[]) calculate("101", "", IValueMeta.TYPE_BINARY, CalculationType.NVL);
        assertArrayEquals(data, calculated);
        data = stringValueMeta.getBinary("011");
        calculated = (byte[]) calculate("", "011", IValueMeta.TYPE_BINARY, CalculationType.NVL);
        assertArrayEquals(data, calculated);
        data = stringValueMeta.getBinary("110");
        calculated = (byte[]) calculate("110", "011", IValueMeta.TYPE_BINARY, CalculationType.NVL);
        assertArrayEquals(data, calculated);
        calculated = (byte[]) calculate("", "", IValueMeta.TYPE_BINARY, CalculationType.NVL);
        assertNull(calculated);
    } catch (HopValueException kve) {
        fail(kve.getMessage());
    }
}

@Test
void testRemainder() {
    assertNull(calculate(null, null, IValueMeta.TYPE_INTEGER, CalculationType.REMAINDER));
    assertNull(calculate(null, "3", IValueMeta.TYPE_INTEGER, CalculationType.REMAINDER));
    assertNull(calculate("10", null, IValueMeta.TYPE_INTEGER, CalculationType.REMAINDER));
    assertEquals(Long.valueOf("1"), calculate("10", "3", IValueMeta.TYPE_INTEGER, CalculationType.REMAINDER));
    assertEquals(Long.valueOf("-1"), calculate("-10", "3", IValueMeta.TYPE_INTEGER, CalculationType.REMAINDER));
    Double comparisonDelta = Double.valueOf("0.0000000000001");
    assertNull(calculate(null, null, IValueMeta.TYPE_NUMBER, CalculationType.REMAINDER));
    assertNull(calculate(null, "4.1", IValueMeta.TYPE_NUMBER, CalculationType.REMAINDER));
    assertNull(calculate("17.8", null, IValueMeta.TYPE_NUMBER, CalculationType.REMAINDER));
    assertEquals(Double.parseDouble("1.4"), (Double) calculate("17.8", "4.1", IValueMeta.TYPE_NUMBER, CalculationType.REMAINDER), comparisonDelta);
    assertEquals(Double.parseDouble("1.4"), (Double) calculate("17.8", "-4.1", IValueMeta.TYPE_NUMBER, CalculationType.REMAINDER), comparisonDelta);
    assertEquals(Double.parseDouble("-1.4"), (Double) calculate("-17.8", "-4.1", IValueMeta.TYPE_NUMBER, CalculationType.REMAINDER), comparisonDelta);
    assertNull(calculate(null, null, IValueMeta.TYPE_BIGNUMBER, CalculationType.REMAINDER));
    assertNull(calculate(null, "16.12", IValueMeta.TYPE_BIGNUMBER, CalculationType.REMAINDER));
    assertNull(calculate("-144.144", null, IValueMeta.TYPE_BIGNUMBER, CalculationType.REMAINDER));
    assertEquals(new BigDecimal("-15.184"), calculate("-144.144", "16.12", IValueMeta.TYPE_BIGNUMBER, CalculationType.REMAINDER));
    assertEquals(Double.valueOf("2.6000000000000005"), calculate("12.5", "3.3", IValueMeta.TYPE_NUMBER, CalculationType.REMAINDER));
    assertEquals(Double.valueOf("4.0"), calculate("12.5", "4.25", IValueMeta.TYPE_NUMBER, CalculationType.REMAINDER));
    assertEquals(Long.valueOf("1"), calculate("10", "3.3", null, IValueMeta.TYPE_INTEGER, IValueMeta.TYPE_NUMBER, IValueMeta.TYPE_NUMBER, CalculationType.REMAINDER));
}

