@Test
void mappingWithNonMatchingColumnNames() {
    NamedFieldsMapping mapping = NamedFieldsMapping.mapping(new String[] { "One", "Two", "Three" }, new String[] { "A", "B", "C" });
    // One -> A
    assertEquals(0, mapping.fieldMetaIndex(0));
    // Two -> B
    assertEquals(1, mapping.fieldMetaIndex(1));
    // Three -> C
    assertEquals(2, mapping.fieldMetaIndex(2));
    mapping = NamedFieldsMapping.mapping(new String[] { "A", "B", "A" }, new String[] { "A", "A" });
    // A -> A
    assertEquals(0, mapping.fieldMetaIndex(0));
    // B -> undefined
    assertEquals(IFieldsMapping.FIELD_DOES_NOT_EXIST, mapping.fieldMetaIndex(1));
    // A -> A
    assertEquals(1, mapping.fieldMetaIndex(2));
    mapping = NamedFieldsMapping.mapping(new String[] { "A", "B", "A" }, new String[] { "A", "X", "B", "Z" });
    // A -> A
    assertEquals(0, mapping.fieldMetaIndex(0));
    // B -> B
    assertEquals(2, mapping.fieldMetaIndex(1));
    // A -> X
    assertEquals(1, mapping.fieldMetaIndex(2));
    assertEquals(IFieldsMapping.FIELD_DOES_NOT_EXIST, // undefined -> undefined
    mapping.fieldMetaIndex(3));
    mapping = NamedFieldsMapping.mapping(new String[] { "A", "B", "A" }, new String[] { "A", "A", "C" });
    // A -> A
    assertEquals(0, mapping.fieldMetaIndex(0));
    // B -> C
    assertEquals(2, mapping.fieldMetaIndex(1));
    // A -> A
    assertEquals(1, mapping.fieldMetaIndex(2));
    mapping = NamedFieldsMapping.mapping(new String[] { "A", "B", "C", "D", "E" }, new String[] { "X", "C", "Y", "B" });
    // A -> X
    assertEquals(0, mapping.fieldMetaIndex(0));
    // B -> B
    assertEquals(3, mapping.fieldMetaIndex(1));
    // C -> C
    assertEquals(1, mapping.fieldMetaIndex(2));
    // D -> Y
    assertEquals(2, mapping.fieldMetaIndex(3));
    // E -> undefined
    assertEquals(IFieldsMapping.FIELD_DOES_NOT_EXIST, mapping.fieldMetaIndex(4));
}

