@Test
void testIsReturn() {
    int lineFeed = '\n';
    int carriageReturn = '\r';
    assertTrue(EncodingType.SINGLE.isLinefeed(lineFeed), "SINGLE.isLineFeed is not line feed");
    assertTrue(EncodingType.DOUBLE_BIG_ENDIAN.isLinefeed(lineFeed), "DOUBLE_BIG_ENDIAN is not line feed");
    assertTrue(EncodingType.DOUBLE_LITTLE_ENDIAN.isLinefeed(lineFeed), "DOUBLE_LITTLE_ENDIAN.isLineFeed is not line feed");
    assertFalse(EncodingType.SINGLE.isLinefeed(carriageReturn), "SINGLE.isLineFeed is carriage return");
    assertFalse(EncodingType.DOUBLE_BIG_ENDIAN.isLinefeed(carriageReturn), "DOUBLE_BIG_ENDIAN.isLineFeed is carriage return");
    assertFalse(EncodingType.DOUBLE_LITTLE_ENDIAN.isLinefeed(carriageReturn), "DOUBLE_LITTLE_ENDIAN.isLineFeed is carriage return");
}

@Test
void testIsLinefeed() {
    int lineFeed = '\n';
    int carriageReturn = '\r';
    assertFalse(EncodingType.SINGLE.isReturn(lineFeed), "SINGLE.isReturn is line feed");
    assertFalse(EncodingType.DOUBLE_BIG_ENDIAN.isReturn(lineFeed), "DOUBLE_BIG_ENDIAN.isReturn is line feed");
    assertFalse(EncodingType.DOUBLE_LITTLE_ENDIAN.isReturn(lineFeed), "DOUBLE_LITTLE_ENDIAN.isReturn is line feed");
    assertTrue(EncodingType.SINGLE.isReturn(carriageReturn), "SINGLE.isReturn is not carriage return");
    assertTrue(EncodingType.DOUBLE_BIG_ENDIAN.isReturn(carriageReturn), "DOUBLE_BIG_ENDIAN.isReturn is not carriage return");
    assertTrue(EncodingType.DOUBLE_LITTLE_ENDIAN.isReturn(carriageReturn), "DOUBLE_LITTLE_ENDIAN.isReturn is not carriage return");
}

